-- 앱별 배포·저장소 연결 기록(1-6). 새 테이블만 추가하고 기존 데이터는 건드리지 않는다.
-- 초기값은 현황 조사 결과(앱 폴더의 git 원격 + 서버 컨테이너 목록)로 채운 것이고, 도메인·배포 방법처럼 자동으로 알 수 없는 값은 통제실에서 고친다.
CREATE TABLE "factory_app_connections" (
    "appSlug" TEXT NOT NULL,
    "folder" TEXT,
    "stack" TEXT,
    "defaultBranch" TEXT,
    "remotes" JSONB,
    "deployServer" TEXT,
    "deployMethod" TEXT,
    "domain" TEXT,
    "containerName" TEXT,
    "services" JSONB,
    "notes" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "factory_app_connections_pkey" PRIMARY KEY ("appSlug")
);

INSERT INTO "factory_app_connections" ("appSlug","stack","defaultBranch","remotes","deployServer","deployMethod","domain","containerName","services","notes","updatedAt") VALUES ('app-kit',NULL,'master','[{"name":"claude-backup","host":"serverpc2","path":"git-server/claude-work/app-kit.git","purpose":"backup"}]'::jsonb,'serverpc2','수동(배포 원격 없음)',NULL,'app-kit-web-1','[]'::jsonb,'추정: 서버2에서 app-kit-web-1 이 돌고 있으나 배포 저장소 원격은 없음',CURRENT_TIMESTAMP) ON CONFLICT ("appSlug") DO NOTHING;
